// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	if m.registryBrowser != nil || m.launchForm != nil || m.resourceForm != nil || m.registryForm != nil ||
		m.networkInspectForm != nil {
		// No tab bar or filter bar in form mode — empty line + info line
		infoLine := m.footer.View(width, m.formStatus())
		if m.registryBrowser != nil && m.registryBrowser.FilterIsVisible() {
			return m.registryBrowser.FilterBarView(width) + "\n" + theme.EmptyLineBg(width) + "\n" + infoLine
		}
		return theme.EmptyLineBg(width) + "\n" + infoLine
	}
	var parts []string
	if bar := m.imageTable.FilterBar(); m.activeTab == tabImages && bar.IsVisible() {
		parts = append(parts, bar.View())
	}
	if crumb := m.renderRegistryBreadcrumb(width); crumb != "" {
		parts = append(parts, crumb)
	}
	// An error or a notice the user has not read yet comes first: the progress
	// of what is still running is the least urgent of the three, and the
	// component is what enforces that order now.
	parts = append(parts, m.renderTabBar(width), theme.EmptyLineBg(width), m.footer.View(width, m.status()))
	return strings.Join(parts, "\n")
}

// status is what the view derives on every frame: the active tab's load, which
// stays first and carries no row detail, then the selected image's own activity
// composed with the running action or the batch progress. None has a timer.
func (m Model) status() sharedcomponents.Status {
	if text, ok := m.loadingLabel(); ok {
		return sharedcomponents.Status{Text: text, Spinner: true}
	}
	st := sharedcomponents.Status{Text: m.actionLine()}
	if st.Text == "" {
		st.Text = sharedcomponents.JobsStatusLine(m.jobs, command.ViewOCIResources)
	}
	moving := false
	if m.activeTab == tabImages {
		if row, ok := m.imageTable.Selected(); ok {
			a := m.rowActivity(row)
			st.Detail = a.Detail
			moving = a.State == indicator.Running || a.State == indicator.Queued
		}
	}
	if st.Text == "" {
		st.Text = m.inlineSecretLine()
	}
	// Only a detail whose dot moves replaces the dot; a failed row's is fixed.
	st.Activity = len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
	return st
}

// inlineSecretLine says why the selected registry's Logged cell is a warning:
// its password sits in the engine's auth file, base64 encoded, which is not
// encryption (§3.68). A state rather than a message — it holds for as long as
// the row is selected, not for three seconds.
func (m Model) inlineSecretLine() string {
	if m.activeTab != tabRegistries || m.authFile == "" {
		return ""
	}
	url := ""
	if reg := m.getSelectedRegistry(); reg != nil {
		url = reg.URL
	} else if group := m.drilledGroup(); group != nil {
		url = group.URL
	}
	if m.registryLoginStatus[url] != docker.LoginInline {
		return ""
	}
	return "Password stored unencrypted in " + m.authFile + " — configure a credential helper"
}

// formStatus is the status while a form or the browser has the viewport. The
// tables behind them are not on screen, so their loads say nothing here; the
// browser's own search does.
func (m Model) formStatus() sharedcomponents.Status {
	if m.registryBrowser != nil {
		if text, ok := m.registryBrowser.LoadingLabel(); ok {
			return sharedcomponents.Status{Text: text, Spinner: true}
		}
		// Past the search, the footer says what the tag under the cursor is doing.
		if row, ok := m.registryBrowser.tagTable.Selected(); ok && m.registryBrowser.state == browserStateTags {
			return sharedcomponents.Status{Detail: row.Activity.Detail}
		}
	}
	if m.networkInspectForm != nil && m.networkInspectForm.loading {
		return sharedcomponents.Status{Text: "Loading containers...", Spinner: true}
	}
	if m.launchForm != nil {
		if st := m.launchForm.ValidationStatus(); st.Text != "" {
			return st
		}
	}
	return sharedcomponents.Status{}
}
// What is being scanned is the registry's answer, not this view's (§3.58).
//
// It held a `scanningImages` map and a `scanning` bool derived from it, and both
// knew only what this view had launched. An image scanned from `:sec` — the same
// image, the same cache entry — went unnoticed here, so `S` offered itself on a
// row already being scanned and the two wrote the same file.
//
// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
// — the image list, the networks, a `docker` action on a row — and a load is not
// a job. What moved is the blink phase of the activity column, which comes from
// the one chain the router holds (D5).

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	// The footer's spinner is deliberately not touched: here it belongs to
	// *loading* — a tab reading its list — and this view's scan progress is on
	// the rows, not in the footer. Two writers of one field would fight every
	// frame a scan and a load overlapped.
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
	}
	return m, nil
}

// handleFrameMsg takes the blink phase of the activity column. Nothing is
// rebuilt: the table reads the phase at render, and so does the footer's
// activity dot. The view's own load spinner is a separate field.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.imageTable.SetBlinkPhase(msg.Blink)
	m.networkTable.SetBlinkPhase(msg.Blink)
	m.volumeTable.SetBlinkPhase(msg.Blink)
	m.registryTable.SetBlinkPhase(msg.Blink)
	if m.registryBrowser != nil {
		m.registryBrowser.SetBlinkPhase(msg.Blink)
	}
	m.footer.SetBlinkPhase(msg.Blink)
	return m, nil
}

